"""Technology fingerprints.

Each entry lists (source, regex) pairs; any match counts as evidence.
Sources: header, html, script (script src URLs), link (link hrefs),
generator (meta generator), cookie (cookie names).
"""

def _s(name, category, *match, version=None):
    return {"name": name, "category": category, "match": list(match), "version": version}


